<?php require __DIR__.'/bootstrap.php'; require_login(); $admin=user()['role']==='admin';
$items=json_decode((string)file_get_contents(__DIR__.'/assets/events.json'),true)?:[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['event_id']??0);if($id<1){flash('Choose a valid event.','error');}elseif(!$pdo){flash('Registration storage is unavailable.','error');}elseif($admin){flash('Administrators cannot register as students.','error');}else{try{$s=$pdo->prepare('INSERT INTO event_registrations(event_id,user_id) VALUES(?,?)');$s->execute([$id,user()['id']]);log_action($pdo,'event_registered',(string)$id);flash('Registration confirmed. See you at the event!');}catch(PDOException $e){flash('You are already registered for this event.','error');}}header('Location:events.php');exit;}
$registered=[];if($pdo&&!$admin){$s=$pdo->prepare('SELECT event_id FROM event_registrations WHERE user_id=?');$s->execute([user()['id']]);$registered=array_column($s->fetchAll(),'event_id');}page_top('Events');?>
<div class="hero"><div><p class="eyebrow">CHARUSAT · CSPIT</p><h1>Campus events</h1><p>Learn, compete and connect with your campus community.</p></div></div>
<section class="grid three"><?php foreach($items as $event):?><article class="panel"><img class="poster" src="<?=e($event['image_url'])?>" alt="<?=e($event['title'])?>"><h2><?=e($event['title'])?></h2><p><?=e($event['description'])?></p><small><?=date('d M Y, H:i',strtotime($event['starts_at']))?> · <?=e($event['location'])?></small><p><span class="badge"><?=e($event['category'])?></span></p><?php if(!$admin):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="event_id" value="<?=$event['id']?>"><button <?=in_array($event['id'],$registered,true)?'disabled':''?>><?=in_array($event['id'],$registered,true)?'Registered':'Register now'?></button></form><?php endif;?></article><?php endforeach;?></section><?php page_bottom();
